parameters.jsCode:
// Extrai o JSON do parecer entre os blocos de conteúdo da API
const blocos = $json.content || [];
const texto = blocos.filter(b => b.type === 'text').map(b => b.text).join('\n');
const limpo = texto.replace(/```json|```/g, '').trim();
const ini = limpo.indexOf('{');
const fim = limpo.lastIndexOf('}');
let parecer;
try {
  parecer = JSON.parse(limpo.slice(ini, fim + 1));
} catch (e) {
  parecer = { status: 'pendente', resumo: 'A IA não retornou um parecer estruturado — validação manual necessária.', achados: [{ campo: 'sistema', nivel: 'atencao', mensagem: 'Falha ao interpretar a resposta da IA.' }] };
}
const entrada = $('Webhook — Entrada do Simulador').first().json.body || {};
return [{ json: { parecer, entrada } }];

